from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

@app.get("/headers")
async def read_headers(user_agent: str = Header()):
    return {"user_agent": user_agent}

client = TestClient(app)

def test_underscore_header():
    # This should fail (return 422) if convert_underscores=True (default)
    # because it should only accept 'user-agent'
    response = client.get("/headers", headers={"user_agent": "test-agent"})
    print(f"Response with user_agent: {response.json()}")
    assert response.status_code == 422, f"Expected 422, got {response.status_code}"

def test_hyphen_header():
    # This should succeed
    response = client.get("/headers", headers={"user-agent": "test-agent"})
    print(f"Response with user-agent: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"user_agent": "test-agent"}

def test_underscore_header_disabled():
    # This should succeed if convert_underscores=False
    @app.get("/headers-underscore")
    async def read_headers_underscore(user_agent: str = Header(convert_underscores=False)):
        return {"user_agent": user_agent}

    response = client.get("/headers-underscore", headers={"user_agent": "test-agent"})
    print(f"Response with user_agent (disabled): {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"user_agent": "test-agent"}

if __name__ == "__main__":
    try:
        test_underscore_header()
        print("test_underscore_header passed")
    except AssertionError as e:
        print(f"test_underscore_header failed: {e}")

    try:
        test_hyphen_header()
        print("test_hyphen_header passed")
    except AssertionError as e:
        print(f"test_hyphen_header failed: {e}")

    try:
        test_underscore_header_disabled()
        print("test_underscore_header_disabled passed")
    except AssertionError as e:
        print(f"test_underscore_header_disabled failed: {e}")

