from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class MyHeaders(BaseModel):
    x_test_header: str

@app.get("/headers")
async def read_headers(headers: MyHeaders = Header()):
    return {"headers": headers}

client = TestClient(app)

def test_underscore_header_model():
    # Should reject 'x_test_header' and accept 'x-test-header'
    # because convert_underscores=True by default
    response = client.get("/headers", headers={"x_test_header": "test-agent"})
    print(f"Response with x_test_header: {response.status_code}, {response.json()}")
    assert response.status_code == 422, f"Expected 422, got {response.status_code}"

def test_hyphen_header_model():
    # Should succeed
    response = client.get("/headers", headers={"x-test-header": "test-agent"})
    print(f"Response with x-test-header: {response.status_code}, {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"headers": {"x_test_header": "test-agent"}}

def test_underscore_header_model_disabled():
    # Should succeed if convert_underscores=False
    # We need a different endpoint for this
    pass

if __name__ == "__main__":
    try:
        test_underscore_header_model()
        print("test_underscore_header_model passed")
    except AssertionError as e:
        print(f"test_underscore_header_model failed: {e}")

    try:
        test_hyphen_header_model()
        print("test_hyphen_header_model passed")
    except AssertionError as e:
        print(f"test_hyphen_header_model failed: {e}")

